
const phone=document.querySelector('#prototype-phone');let current='home';let truthResolved=false;let confirmedPrefs=[{value:'每次步行不超过 30 分钟',source:'你在 10月25日确认 · 跨趟适用',icon:'footprints'},{value:'优先公共交通',source:'你在 9月12日确认 · 跨趟适用',icon:'train-front'}];let promotionState='pending';
function show(name){current=name;phone.innerHTML=SCREENS[name];phone.dataset.state=name;if(name==='sidebar'){const src=SCREENS.sidebar;const idx=src.indexOf('<div class="sidescrim"');phone.innerHTML='<div class="bodypanel" inert aria-hidden="true">'+src.slice(0,idx)+'</div>'+src.slice(idx);phone.querySelector('aside').setAttribute('role','dialog');phone.querySelector('aside').setAttribute('aria-label','行程目录');phone.querySelector('aside').setAttribute('aria-modal','true');}if(truthResolved&&name==='home'){phone.querySelector('.truth-banner')?.remove();phone.querySelector('.notification')?.remove();}if(truthResolved&&name==='sidebar')phone.querySelector('.navrow[data-go=truth] em')?.remove();if(truthResolved&&name==='itinerary'){const t=phone.querySelector('.timeitems button.amber');if(t){t.textContent='已核对 · 今天15:56通知';t.classList.remove('amber');}}if(truthResolved&&name==='truth'){phone.querySelector('.pageheader p').textContent='行程真相 · 已核对';const b=phone.querySelector('[data-confirm-truth]');b.textContent='已核对并更新演示行程';b.disabled=true;}if(name==='memory')renderMemory();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));}
function toast(text){phone.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=text;phone.append(el);el.onclick=()=>el.remove();}
function modal(title,text,cta,cb){const e=document.createElement('div');e.className='modal-overlay';e.setAttribute('role','dialog');e.setAttribute('aria-modal','true');e.setAttribute('aria-label',title);e.innerHTML=`<div class="modal"><span class="sheettitle">演示操作</span><h2>${title}</h2><p>${text}</p><button class="primary" data-final>${cta}</button><button class="secondary" data-dismiss>取消</button></div>`;phone.append(e);e.querySelector('[data-final]').focus();e.querySelector('[data-dismiss]').onclick=()=>e.remove();e.querySelector('[data-final]').onclick=()=>{e.remove();cb();};}
document.addEventListener('click',e=>{const a=e.target.closest('button,[data-close-sidebar]');if(!a)return;if(a.dataset.view){show(a.dataset.view);return;}if(a.dataset.go){show(a.dataset.go);return;}if(a.hasAttribute('data-sidebar')){show('sidebar');phone.querySelector('[data-close-sidebar].round')?.focus();return;}if(a.hasAttribute('data-close-sidebar')){show('home');return;}if(a.hasAttribute('data-nav')){modal('即将打开步行导航','目标：上野站。原生版将打开系统地图；当前演示不调用定位或导航服务。','预览完成',()=>toast('演示结束。没有读取定位或打开导航。'));}if(a.hasAttribute('data-confirm-truth')){truthResolved=true;a.disabled=true;a.innerHTML='已更新本次演示记录';phone.querySelector('.pageheader p').textContent='行程真相 · 已核对';a.style.background='#267660';toast('已将演示行程时间更新为 19:05。没有改签机票。');}if(a.hasAttribute('data-source')){modal('来源与提取字段','演示来源：本地样例通知。实际产品需展示原文、收到时间、提取字段及版本。此处不是航空公司实时数据。','我知道了',()=>{});}if(a.hasAttribute('data-pay-preview')){modal('核对：JPY ¥2,580','Skyliner 指定席 · 1 位成人。演示退款手续费 ¥220。实际产品接下来打开系统支付，仍需用户授权。','模拟确认（不会付款）',()=>toast('模拟确认完成。没有实际支付，也没有出票。'));}if(a.hasAttribute('data-delete-pref')){modal('删除这条旅行偏好？','删除后，这条偏好不再参与后续推荐；原始票据不会随偏好一起删除。','删除演示偏好',()=>{const value=a.closest('.prefrow').querySelector('b').textContent;confirmedPrefs=confirmedPrefs.filter(p=>p.value!==value);renderMemory();});}if(a.hasAttribute('data-promote')){confirmedPrefs.push({value:'优先安静的客房',source:'你刚刚明确确认 · 可随时删除',icon:'bookmark'});promotionState='confirmed';renderMemory();}if(a.hasAttribute('data-dismiss-promotion')){promotionState='dismissed';renderMemory();}if(a.hasAttribute('data-memory-tab')){phone.querySelectorAll('[data-memory-tab]').forEach(t=>t.classList.toggle('active',t===a));const s=phone.querySelector('.memorysection');if(a.dataset.memoryTab==='trip')s.innerHTML='<div class="memoryheading">这一趟 · 可归档</div><div class="prefrow"><div><b>去机场的交通方案仍待确认</b><p>开放环 · 10月29日 · 来源：本趟行程</p></div></div>';else if(a.dataset.memoryTab==='today')s.innerHTML='<div class="memoryheading">今天 · 临时上下文</div><div class="prefrow"><div><b>今天想轻松一点</b><p>当天结束后到期，不自动进入长期偏好</p></div></div>';else show('memory');}if(a.hasAttribute('data-archive'))modal('归档这一趟东京旅行？','生成旅程摘要；详细记录进入归档。长期偏好与敏感凭证分别管理。','模拟归档',()=>toast('东京旅行已在当前演示中归档。'));if(a.hasAttribute('data-ask'))modal('只围绕这趟旅程','原生版支持语音与文字。本原型用任务卡展示意图，未接入模型、麦克风或个人数据。','看看行程',()=>show('itinerary'));});
show(new URLSearchParams(location.search).get('screen')||'home');

document.addEventListener('keydown',e=>{const scope=phone.querySelector('.modal-overlay')||phone.querySelector('.sidebar');if(!scope)return;if(e.key==='Escape'){e.preventDefault();if(scope.classList.contains('sidebar'))show('home');else scope.remove();return;}if(e.key==='Tab'){const all=[...scope.querySelectorAll('button:not([disabled]),[href],input')];if(!all.length)return;const a=all[0],b=all.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}}});

function renderMemory(){const section=phone.querySelector('.memorysection');if(!section)return;section.innerHTML='<div class="memoryheading"><span>已确认的偏好</span><b>'+confirmedPrefs.length+'</b></div>'+confirmedPrefs.map(p=>'<div class="prefrow"><i class="ico" style="--icon:url(assets/icons/'+p.icon+'.svg)"></i><div><b>'+p.value+'</b><p>'+p.source+'</p></div><button class="round small" data-delete-pref aria-label="删除'+p.value+'"><i class="ico" style="--icon:url(assets/icons/trash-2.svg)"></i></button></div>').join('');const promotion=phone.querySelector('.promotion');if(promotion&&promotionState!=='pending')promotion.remove();}
